 // Suchliste: je Adresse ein Eintrag; bei gleicher Adresse hat das Gebäude im Modell und mit Wohnnutzung Vorrang.
 const rank=b=>(b.model?2:0)+(b.category!==1060?1:0);for(const [egid,b] of Object.entries(register.buildings))for(const a of b.addresses){const key=a.label.toLowerCase(),old=addressIndex.get(key);if(!old||rank(b)>rank(old.entry))addressIndex.set(key,{label:a.label,egid:Number(egid),entry:b,x:a.x,z:a.z});}
