function info(title,html){$('info-title').textContent=title;$('info-content').innerHTML=html;$('info-dialog').showModal();}
$('help').addEventListener('click',()=>info('Das Dorf erkunden.','<p>Die Bedienung folgt Google Maps: Mit der linken Maustaste verschiebst du die Karte. Mit der rechten Maustaste oder Ctrl + Ziehen drehst und neigst du die Ansicht. Das Mausrad zoomt auf die Stelle unter dem Mauszeiger, ein Doppelklick zoomt dorthin. Pfeiltasten verschieben, Plus und Minus zoomen. Auf dem Handy: ein Finger verschiebt, zwei Finger zoomen, drehen und neigen. Ein Klick auf den Kompass richtet nach Norden aus. Auf Strassenhöhe schaust du dich mit der linken Maustaste oder einem Finger um.</p><p>Die Adresse im Browser merkt sich deine Ansicht. Kopiere sie, um genau diesen Blick weiterzugeben.</p><p>Unter «Orte» findest du Adressen, Strassen und ausgewählte Plätze wie die Gemeindeverwaltung oder den Bahnhof. Du kannst Gebäude, Felder und Ortsmarken auch direkt anklicken. Unter «Ebenen» lassen sich einzelne Bestandteile ausblenden.</p><p>Oben rechts wählst du Tageszeit und Datum und spielst einen Tag oder ein Jahr im Zeitraffer ab. Die Wetteranzeige daneben schaltet das aktuelle Wetter ein und aus.</p><p>«Zug» und «Landwirtschaft» zeigen die bewegten Szenen aus der Nähe. Unter «Ansicht» hältst du mit «Dorfleben in Bewegung» Zug, Fahrzeuge und Menschen an; die Ebene «Fahrzeuge und Menschen» blendet sie aus. «Auf Strassenhöhe» und «Nächster Blick» zeigen drei feste Ansichten entlang der Hauptstrasse.</p><p>«Dreiecksnetz zeigen» macht sichtbar, dass alles im Bild aus 3D-Geometrie besteht.</p>'));
$('sources').addEventListener('click',()=>info('Daten & Genauigkeit.','<p><strong>Amtliche Vermessung:</strong> Vorplätze, Zufahrten und Hofflächen, Gartenanlagen, Strassen- und Wegflächen, Trottoirs, Mauern, Unterstände und Kleinbauten stammen mit Lage und Umriss aus der amtlichen Vermessung des Kantons Freiburg (bezogen über geodienste.ch) und sind an den Gebäuden des Modells eingepasst. Die amtliche Vermessung kennt weder Belag noch Höhe: Farben und Oberflächen, die Mauerhöhe von 0,9 m, die Höhe der Unterstände von 2,5 m und der Kleinbauten von 2,7 m sind Annahmen. Strassen werden weiterhin zusätzlich als Bänder entlang der Strassenachsen gezeichnet. Der Belag der Vorplätze (Asphalt, Kies, Platten), begrünte Teile befestigter Flächen sind aus der Farbe von SWISSIMAGE-Luftbildern geschätzt; die Luftbilder selbst werden nicht angezeigt. Die Unterscheidung von Asphalt und Kies ist unsicher, Zäune sind nicht erfasst.</p><p><strong>Baumhöhen:</strong> Höhe und Kronenbreite der Einzelbäume, die Höhe des Waldes sowie Standort und Höhe der Bäume, Sträucher und Hecken in den Gärten stammen aus den Laserdaten von swisstopo (Oberflächenmodell minus Geländemodell). Baumart, Kronenform und die Standorte der einzelnen Waldbäume bleiben illustrativ.</p><p><strong>Grenzen, Leitung und Vordächer:</strong> Liegenschaftsgrenzen (Ebene «Liegenschaftsgrenzen», ein Klick zeigt Parzellennummer und Fläche), Maststandorte und Achse der Hochspannungsleitung sowie die Umrisse der Vordächer stammen aus der amtlichen Vermessung. Masthöhe, Mastform, Seile und Durchhang sind angenommen. Die Höhe der Vordächer stammt aus den Laserdaten, wo diese plausibel sind. Die Grenzen dienen der Orientierung und sind nicht rechtsverbindlich.</p><p><strong>Tagesablauf:</strong> Autos, Bahnpendler und Velos folgen der dargestellten Uhrzeit: Am Morgen fahren die Autos von den Wohnhäusern weg und die Pendler gehen zum Bahnhof, über Mittag und am Abend kommen sie zurück; nachts stehen die Autos auf den Vorplätzen. Welche Häuser Wohnhäuser sind und wie viele Wohnungen sie haben, stammt aus dem Gebäuderegister. Wer wann fährt, die Zahl der Autos, der Durchgangsverkehr und die Verkehrsdichte sind frei gestaltet und zur Lesbarkeit dichter als in Wirklichkeit; es sind keine Zählungen. Der Zug verkehrt in dichter Folge und nicht nach Fahrplan, zwischen 00:45 und 04:45 ruht er.</p><p><strong>Kehricht, Schulbus und Freizeitorte:</strong> Die 43 Kehrichtabfuhrplätze (Ebene «Kehrichtabfuhrplätze»), die Abfuhrtage 2026, die Haltestellen und Fahrzeiten des Schulbusses nach Kerzers sowie Namen und Beschreibungen der Natur- und Freizeitorte stammen aus den Unterlagen der Gemeinde Fräschels. An Abfuhrtagen stehen die Container bereit und der Kehrichtwagen fährt die Plätze ab; an Werktagen fährt der Schulbus nach Fahrplan und die Kinder gehen zur Haltestelle. Frei gestaltet sind die Fahrzeuge, Fahrwege und Reihenfolge der Abfuhr, die Uhrzeit des Kehrichtwagens (ab 08:00), Zahl und Wohnort der Kinder sowie die Form der Gegenstände. Die Lage von Chutzenstein, Grillplatz und Waldschenke ist aus den Angaben der Gemeinde erschlossen und nicht gesichert; Schulferien sind nicht berücksichtigt.</p><p><strong>Tiere und Feldarbeit:</strong> Kühe stehen von Mitte April bis Ende Oktober auf den als Weide gemeldeten Flächen, Störche schreiten von März bis September über Wiesen und Äcker, am Tag zieht ein Vogelschwarm über die Felder. Der Traktor arbeitet auf einem gemeldeten Feld, auf dem nach dem Kalender gerade Ernte, Saat, Bodenbearbeitung oder Mähen ansteht; im Winter und nachts steht er. Ob und wie viele Tiere es gibt, ihr Verhalten und die Wahl des Feldes sind frei gestaltet.</p><p><strong>Beleuchtung:</strong> An der Hauptstrasse stehen innerorts LED-Leuchten mit hellem, klar begrenztem Licht auf der Fahrbahn, in den Quartieren ältere Natriumdampflampen mit rötlichem, rundum strahlendem Licht (Angabe des Auftraggebers). Die Standorte sind nicht erhoben: Die Leuchten stehen regelmässig am Strassenrand, nie auf der Fahrbahn. In den Häusern brennt Licht nach einem erfundenen Tageslauf je Haus und Zimmer.</p><p><strong>Nacht:</strong> Der Mond steht an seiner gerechneten Stelle und zeigt die richtige Phase (auf rund 2° genau, zur Sichtbarkeit vergrössert); steht er am Himmel, kommt das Nachtlicht aus seiner Richtung und ist bei Vollmond heller. Die Sterne sind zufällig verteilt, keine echten Sternbilder. Die Fenster gehen nach einem erfundenen Tageslauf einzeln an und aus; der Kaminrauch bei Kälte entspringt dem Dach ausgeloster Häuser, Kamine sind nicht erhoben.</p><p><strong>Wind, Wolken und Ton:</strong> Baumkronen und Getreide bewegen sich mit der gemeldeten Windstärke und -richtung, Wolkenschatten ziehen bei lockerer Bewölkung über das Gelände. Form und Lage der Wolken und ihrer Schatten sind frei gestaltet und stimmen nicht mit dem Himmel über Fräschels überein. Die Geräuschkulisse (Knopf «Ton») wird im Browser erzeugt und ist synthetisch; es sind keine Aufnahmen. Steht das Dorfleben still (unter «Ansicht»), ruht auch der Wind.</p><p><strong>Felder:</strong> Umriss und Kultur jedes Feldes stammen aus den gemeldeten landwirtschaftlichen Nutzungsflächen des Kantons Freiburg (Bezugsjahr auf der Karte beim Anklicken). Wann ein Feld grün, reif oder abgeerntet ist, folgt einem festen Kalender mit üblichen Terminen und ist Gestaltung, ebenso Reihen und Fahrgassen. Im Umland ausserhalb der Gemeinde sind die Felder weiterhin frei gestaltet.</p><p><strong>Gebäudeangaben:</strong> Adresse, Nutzung, Baujahr oder Bauzeit, Geschosse, Wohnungen und Grundfläche stammen aus dem Gebäude- und Wohnungsregister des Bundes (BFS) und sind nicht vor Ort geprüft; wo das Register nichts führt, bleibt die Angabe weg. Angaben zu Heizung, Energie und einzelnen Wohnungen sind nicht übernommen.</p><p><strong>Sonnenstand und Jahreszeit:</strong> Die Richtung des Sonnenlichts und der Wechsel von Tag, Dämmerung und Nacht sind aus Datum und Uhrzeit für Fräschels gerechnet und werden alle fünf Minuten nachgeführt. Über die Zeitanzeige oben rechts lassen sich Tageszeit und Datum frei wählen und ein Tag oder ein Jahr im Zeitraffer abspielen; Auf- und Untergang gelten für einen flachen Horizont. Lichtfarbe und Himmel sind Gestaltung. Die Laubfarben folgen festen Stichtagen im Jahr, nicht der tatsächlichen Witterung; Wiesen und Felder bleiben das ganze Jahr gleich.</p><p><strong>Stimmung und Wetter:</strong> Abendlicht, Himmel, Dunst, Farbgebung und Tiefenunschärfe sind Gestaltung. Büsche und zusätzliche Garten- und Obstbäume um die Häuser sowie Felder und Bäume ausserhalb der Gemeindegrenze sind illustrativ und nicht erhoben; das Gelände im Kartenausschnitt stammt aus den Geodaten. Das angezeigte Wetter (Bewölkung, Regen, Schnee, Nebel, Tag oder Nacht) wird alle 15 Minuten bei Open-Meteo abgerufen; dafür verbindet sich dein Browser mit api.open-meteo.com. Welche Fenster leuchten, ist zufällig. Über die Wetteranzeige lässt sich das Live-Wetter ausschalten. Unter «Ansicht» wechselt «Stimmung und Wetter» zur sachlichen Darstellung ohne diese Zutaten.</p><p><strong>Grafikvorschau:</strong> Ausgearbeitete Oberflächen im Bahnhofsumfeld, einzelne Baumblätter, Wiesenhalme und warmes Sonnenlicht. Materialtexturen werden lokal erzeugt und sind keine Luftbilder. Materialausführung und Vegetation sind angenähert. Das Wartehäuschen steht parallel zur Gleisrichtung.</p><p><strong>Bahnhof und Werkhof:</strong> Perron mit Sicherheitslinie, Wartehäuschen, Sitzbank, Stationsschild und Informationstafel. Werkhof und Sammelstelle auf dem Kiesplatz nördlich des Bahnhofs, mit Alu-, Altglas- und Altkleidercontainern. Lage und Sammelarten durch einen Einwohner bestätigt; Ausgestaltung und Höhen angenähert.</p><p><strong>Neue Ausstattung:</strong> Sportbelag, Spielfeldlinien, Basketballkörbe, Kies-Spielbereich, Spielgeräte, Sitzbänke, nachgezeichnete Gärten und Terrassen, Gartenmöbel, Einfriedungen, Strassenlaternen, Parkflächen und Bewässerungsbecken. Sichtbare Flächen wurden aus hochauflösendem SWISSIMAGE interpretiert. Gerätetypen, Höhen, Bepflanzung und Ausstattung sind angenähert; insbesondere Laternenpositionen sind keine einzeln erhobenen Standorte. Parkierte Fahrzeuge sind illustrative Beispiele.</p><p><strong>Modelliert:</strong> Trottoirs, Bordsteine, elf Vorplatz- und Einfahrtsflächen sowie drei Fussgängerstreifen entlang der Hauptstrasse; Gelände, Gebäude, Strassen und Wege, Gleise und Schwellen, Bäume, Hecken, Pools, Feldflächen und Pflanzenreihen. Keine Satelliten- oder Luftbildtextur wird angezeigt.</p><p><strong>Verkehrswege und Gebäudedetails:</strong> Strassen- und Gleiskorridore sind für eine ruhigere Darstellung geglättet. Einschnitte und Aufschüttungen sind angenähert. Einzelne Dachziegel, Rinnen, Fallrohre, Türgewände und weitere Fassadendetails folgen den vorhandenen Gebäudeformen; ihre Gestaltung ist nicht gebäudeweise vermessen.</p><p><strong>Dorfleben:</strong> Zug, Traktor, Bauer und Fussgänger sind gestaltete Beispiele mit simulierten Bewegungen. Sie zeigen keine aktuellen Ereignisse, echten Personen oder Fahrplandaten.</p><p><strong>Aus Geodaten:</strong> Gebäudeformen aus swissBUILDINGS3D, Gelände aus dem swisstopo-Terrain-Dienst, Strassenachsen, Baumpositionen und Poolumrisse aus den swisstopo-Vektordaten.</p><p><strong>Angenähert:</strong> Strassenbreiten und Markierungen, Fassadenfarben und Fenster, Baumarten und Kronenformen, Feld- und Heckengrenzen. Dachmaterialfarben wurden aus SWISSIMAGE abgeleitet; sie sind keine Bildtexturen. Feld- und Heckengrenzen wurden anhand von SWISSIMAGE angenähert. Sie sind keine Katastergrenzen. Private Gartenflächen und weitere kleine Objekte sind noch nicht vollständig erfasst.</p><p>Die Szene umfasst die gesamte Gemeindefläche von rund 311 Hektaren entlang der amtlichen Grenze (2026). Waldgrenzen stammen aus Geodaten; einzelne Bäume im Wald sind illustrativ verteilt. Die Feldgrenzen ausserhalb des Dorfkerns wurden anhand von SWISSIMAGE angenähert; Fruchtarten sind Beispiele. Das verlinkte Strassenvideo wurde als visuelle Referenz betrachtet; Für vier Gebäude wurden Fassadentypen mit Fensterläden beziehungsweise Holzflächen angenähert; die Zuordnung der historischen Ansichten ist vorläufig. Eine gebäudeweise Fassadenvermessung liegt noch nicht vor. Google Street View wurde nicht verwendet. Alle Modelldaten liegen lokal vor; die Szene benötigt nach dem Download keinen externen Geodatendienst.</p><p>Geodaten © swisstopo. <a href="https://www.swisstopo.admin.ch/de/nutzungsbedingungen-kostenlose-geodaten-und-geodienste" target="_blank" rel="noopener">Nutzungsbedingungen</a>.</p>'));
$('close-info').addEventListener('click',()=>$('info-dialog').close());
export async function exportGLB(){if(!model)throw new Error('Modell lädt noch');exporting=true;const mood=!!atmosphere?.enabled;atmosphere?.setEnabled(false);model.daily?.setClock(model.daily.diagnostics().minutes,{lights:false});const qualityEnabled=model.quality.enabled;model.quality.setEnabled(true);const detailMeshes=model.quality.group.children.map(o=>[o,o.visible]);for(const [o]of detailMeshes)o.visible=true;model.root.traverse(o=>{if(o.userData.detailLOD){o.createDetails?.();detailMeshes.push([o,o.visible]);o.visible=true;}});model.root.traverse(o=>{if(o.userData.forestFar){detailMeshes.push([o,o.visible]);o.visible=false;}});model.quality.update(0);const restoreLife=model.life.prepareExport();const enabled=model.refinementEnabled,hidden=Object.values(model.groups).filter(g=>!g.visible);model.setRefinement(true);for(const group of Object.values(model.groups))group.visible=true;model.cadastre?.sync();model.root.updateMatrixWorld(true);try{return await new GLTFExporter().parseAsync(model.root,{binary:true,onlyVisible:true});}finally{for(const [o,visible]of detailMeshes)o.visible=visible;restoreLife();model.quality.setEnabled(qualityEnabled);exporting=false;model.setRefinement(enabled);for(const group of hidden)group.visible=false;model.cadastre?.sync();atmosphere?.setEnabled(mood);syncTime();shadowAnchor=null;render();}}
$('export').addEventListener('click',async()=>{const button=$('export');button.disabled=true;toast('3D-Gemeindemodell wird exportiert …');try{const bytes=await exportGLB();const url=URL.createObjectURL(new Blob([bytes],{type:'model/gltf-binary'}));const a=document.createElement('a');a.href=url;a.download='Fraeschels-Gemeinde-3D.glb';a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);toast('GLB-Datei erstellt.');}catch(error){console.error(error);toast('Export fehlgeschlagen: '+error.message);}finally{button.disabled=false;}});
// Bildschirmpunkt eines Modellpunkts (für Prüfungen, die im Bild klicken)
export function screenPoint(x,y,z){const v=new T.Vector3(x,y,z).project(camera),r=renderer.domElement.getBoundingClientRect();return [r.left+(v.x+1)/2*r.width,r.top+(1-v.y)/2*r.height,v.z];}
export function diagnostics(){let meshes=0,textures=0;model?.root.traverse(obj=>{if(obj.isMesh){meshes++;const mats=Array.isArray(obj.material)?obj.material:[obj.material];for(const mat of mats)if(mat.map)textures++;}});return {ready:!!model,qualityEnabled:model?.quality.enabled,stats:model?.stats,meshes,imageTextures:textures,wireframe,orbiting,lifePlaying,life:model?.life.diagnostics(),grading:model?.grading,areaHa:311,boundaryYear:2026,selectedEGID:selected?.userData.egid,layers:model?Object.fromEntries(Object.entries(model.groups).map(([k,g])=>[k,g.visible])):{},streetNames:model?.streets.map(s=>s.name),labelsVisible,dioramaEnabled,ambientOcclusion:!!atmosphere?.ambientOcclusion,quarter:model?.quarter?.stats||null,townHall:model?.townHall?.stats||null,ofenhaus:model?.ofenhaus?.stats||null,lighting:model?.streetLights?{...model.streetLights.stats,on:model.streetLights.on}:null,community:model?.community?.diagnostics(),wildlife:model?.wildlife?.diagnostics(),farm:model?.crops?.farm,night:atmosphere?.night,daily:model?.daily?.diagnostics(),motion:atmosphere?.motion,sound:{enabled:soundscape.enabled,levels:soundscape.levels},crops:model?.crops?{...model.crops.stats,shown:model.crops.shown}:null,register:register?{buildings:Object.keys(register.buildings).length,addresses:addressIndex.size}:null,time:atmosphere?.time,weather:atmosphere?.weather,weatherLive,mood:atmosphere?.stats,refinementEnabled:model?.refinementEnabled,streetViewIndex,cameraPosition:camera?.position.toArray(),cameraTarget:controls?.target.toArray(),cameraFov:camera?.fov,cameraTerrainHeight:camera&&model?model.height(camera.position.x,camera.position.z):undefined,triangles:renderer?.info.render.triangles};}
init();
